import{z as i,x as c,o as l,c as A,q as o,j as t,D as e,d as s,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"工具 schema 训练","description":"","frontmatter":{"title":"工具 schema 训练","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/tool-schema-sft.md","filePath":"llm/tool-schema-sft.md","lastUpdated":1791413859000}'),h={name:"llm/tool-schema-sft.md"};function m(B,a,d,p,S,_){const E=c("Mermaid");return l(),A("div",null,[a[2]||(a[2]=o('<h1 id="工具-schema-训练" tabindex="-1">工具 schema 训练 <a class="header-anchor" href="#工具-schema-训练" aria-label="Permalink to &quot;工具 schema 训练&quot;">​</a></h1><div class="epigraph"><p>工具调用不是散文里的意愿，而是对一份 JSON Schema 的条件生成；监督要落在名字、必填字段与类型上，否则运行时只能靠正则抢救。</p><footer>—— 对照 OpenAI 式 function calling 训练；Schick 等 Toolformer 的自监督插入则是另一条数据路</footer></div><p><a href="/llm/plan-vs-react">上一课</a> 把控制流分成反应与先规划。两条路都假设模型能产出<strong>合法调用</strong>。<a href="/llm/function-calling">Function calling</a> 定义了协议信封；本课补训练缺口：如何用 schema 约束的 SFT（及少量 RL）让模型在该调时调、参数可过校验器。后面的多步信用、沙箱默认策略已经会说「这门语言」，而不是只会 ReAct 示范里的假动作字符串。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>提示里塞工具说明，少样本能让模型偶尔写出对的 JSON，但工具一多、嵌套一深、必填字段一多，合法率下降。解码端用 <a href="/llm/json-schema-decode">JSON schema</a> 约束可以提高合法率，却不能教「何时调用、调用哪一个」——那是决策，要靠数据。Toolformer 用自监督在文本中插入 API 调用；当代助手则用带 <code>tools</code> 字段的对话轨迹做 SFT。本课走后者：显式 schema + 角色交替的监督，与协议课对齐。</p><p><span class="marginnote">「约束解码」是在生成时套一个语法滤镜：凡是会让 JSON 不合法的字，直接从候选里删掉。它能保证「写得对」，却保证不了「该不该写」——要不要调用、选哪个工具，仍得靠训练数据教会。</span></p><p>缺口还包括负例：不该调用时调用（幻觉工具、该用记忆却去搜）、该调用却闲聊编造。只有正例 SFT 会过度调用。轨迹里需要「直接回答」与「先调工具」两种教师。</p><p><span class="marginnote">常见误区：以为工具数据越多越好、全是调用轨迹。若没有「用户只是打招呼、模型直接回答」这类负例，模型会学成「见请求就调工具」，闲聊也去搜一遍——过度调用比不会调用更伤产品。</span></p>',8)),(l(),t(n,null,{default:e(()=>[r(E,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E7%94%A8%E6%88%B7%E8%AF%B7%E6%B1%82%20%2B%20%E5%B7%A5%E5%85%B7%E6%B8%85%E5%8D%95%22%5D%20--%3E%20D%7B%22%E5%86%B3%E7%AD%96%EF%BC%9A%E8%A6%81%E4%B8%8D%E8%A6%81%E8%B0%83%E3%80%81%E8%B0%83%E5%93%AA%E4%B8%AA%22%7D%0A%20%20D%20--%3E%7C%22%E4%B8%8D%E9%9C%80%E8%A6%81%22%7C%20TXT%5B%22%E7%9B%B4%E6%8E%A5%E5%9B%9E%E7%AD%94%22%5D%0A%20%20D%20--%3E%7C%22%E8%A6%81%E8%B0%83%22%7C%20G%5B%22%E7%BB%93%E6%9E%84%E5%8C%96%E7%94%9F%E6%88%90%EF%BC%9A%E5%AD%97%E6%AE%B5%E5%90%8D%E4%B8%8E%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20G%20--%3E%20V%7B%22%E6%A0%A1%E9%AA%8C%E5%99%A8%E9%80%9A%E8%BF%87%EF%BC%9F%22%7D%0A%20%20V%20--%3E%7C%22%E5%90%A6%22%7C%20R%5B%22%E5%8F%AA%E8%83%BD%E9%9D%A0%E6%AD%A3%E5%88%99%E6%8A%A2%E6%95%91%EF%BC%9A%E7%BA%BF%E4%B8%8A%E4%BA%8B%E6%95%85%22%5D%0A%20%20V%20--%3E%7C%22%E6%98%AF%22%7C%20E%5B%22%E5%AE%BF%E4%B8%BB%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h3 id="schema-是词表上的子集-不是自然语言同意义" tabindex="-1">Schema 是词表上的子集，不是自然语言同意义 <a class="header-anchor" href="#schema-是词表上的子集-不是自然语言同意义" aria-label="Permalink to &quot;Schema 是词表上的子集，不是自然语言同意义&quot;">​</a></h3><p>同一语义 <code>city: 北京</code> 写成错字段名就不执行。损失必须对字段名敏感，对无关闲聊不敏感。实现上对 tool_call token 加权、对链式思考（若有）降权，避免模型学会在 Thought 里把参数写对、在 JSON 里写错——运行时只看 JSON。<span class="marginnote">训练用的 schema 与线上白名单必须同版本。多一个未部署的工具名，模型会点名幽灵函数；少一个，会把该任务编成散文。这与 MoE 路由「选不存在的专家」类似，属于接口漂移。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="正例、负例与约束解码何时开" tabindex="-1">正例、负例与约束解码何时开 <a class="header-anchor" href="#正例、负例与约束解码何时开" aria-label="Permalink to &quot;正例、负例与约束解码何时开&quot;">​</a></h3><p>数据：每条样本含系统侧工具列表（JSON Schema）、用户请求、可选多轮，助手要么 <code>tool_calls</code> 要么纯文本。执行结果以 tool 角色回填后再答。SFT 在助手与后续轮上做 CE。合成数据：用强模型或脚本对 schema 生成合法 / 非法对照，非法仅作负例（损失推向「不这样写」或拒绝）。真实日志要脱敏、并过滤执行失败但教师仍当成功的脏轨迹。</p><p>约束解码可在训练后期或只在推理开。训练全程硬约束会让模型从未见过「被纠正的非法前缀」，线上一旦约束关闭就会崩。建议训练不依赖约束、推理加约束当保险。</p>',6)),(l(),t(n,null,{default:e(()=>[r(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCH%5B%22%E5%B7%A5%E5%85%B7%20JSON%20Schema%22%5D%20--%3E%20SFT%5B%22%E7%9B%91%E7%9D%A3%EF%BC%9A%E5%90%88%E6%B3%95%20tool_calls%20%E6%88%96%E7%9B%B4%E7%AD%94%22%5D%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20SFT%0A%20%20SFT%20--%3E%20DEC%5B%22%E6%8E%A8%E7%90%86%E5%8F%AF%E9%80%89%E7%BA%A6%E6%9D%9F%E8%A7%A3%E7%A0%81%22%5D%0A%20%20DEC%20--%3E%20RT%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E6%A0%A1%E9%AA%8C%E5%86%8D%E6%89%A7%E8%A1%8C%22%5D%0A%20%20RT%20--%3E%20OBS%5B%22tool%20%E8%A7%82%E5%AF%9F%E5%9B%9E%E5%A1%AB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Schema SFT 把工具名与参数键变成高频模式，降低合法调用的损失。决策边界来自请求与说明文本的对应：说明写得差，模型会调错工具，这是文档问题不是优化器问题。工具说明应像代码注释一样版本化，并出现在训练分布里——只在线上改 description、不重训，等于域移。</p><p>多工具时，调用哪个是分类问题，参数是结构化生成。两者可分阶段：先训选工具（名字），再训填槽。联合训更简单，但稀有工具会饿死，类似 MoE 崩溃。应对稀有工具过采样或分组训练。</p><p><span class="marginnote">「稀有工具饿死」好比班级里冷门题型没人练：一万条轨迹里九千条在调搜索，日历 API 只出现五十次，模型对它的参数就背不熟。过采样就是给冷门工具单独加课，把出现次数拉回同一量级。</span></p><p><span class="marginnote">ReAct 散文格式与 JSON tool_calls 不要在同一检查点里用两套教师混得无标记。迁移时要有显式格式标记或单独 SFT 阶段，否则模型会在 JSON 里夹 Thought，破坏解析器。</span></p><h3 id="与可验证奖励的衔接" tabindex="-1">与可验证奖励的衔接 <a class="header-anchor" href="#与可验证奖励的衔接" aria-label="Permalink to &quot;与可验证奖励的衔接&quot;">​</a></h3><p>若工具有单测式校验（SQL 结果对、代码通过），可在 schema SFT 之后用 <a href="/llm/verifiable-reward">可验证奖励</a> 对「最终任务成功」做 RL，而不是对 JSON 合法做 RL——合法已由 SFT 与约束覆盖。对合法率做 RL 信号太密且与约束重复。RL 应奖终态，合法当过滤。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MCP / 动态工具列表使训练时看不见的 schema 在线上出现。泛化依赖模型读 JSON Schema 的能力，应用一批「训练期未出现的工具」做评测，而不是只测见过的日历 API。评测协议课的工具面版本与此对应：泛化集 vs 闭集。</p><p>过长 schema 占窗口，真正的用户话被挤掉。应对工具做检索（只放可能相关的定义）——这是另一层路由，错误会让模型看不见该用的工具。训练应包含「列表被截断 / 被检索」的情境，否则线上一切换检索就掉点。</p><p><span class="marginnote">Toolformer 不需要预先声明完整工具清单，靠自监督插入；本课的产品路径是声明式 schema。两者数据不可互换。附录论文课会对照原文，主干只要求你锁住声明式这一条。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Schema SFT 教合法调用与何时调用；约束解码是推理保险不是训练替代。</li><li>正负例都要：过度调用与幻觉工具来自缺负例。</li><li>损失对准 tool_call 字段；schema 与白名单同版本。</li><li>稀有工具会饿死；动态工具要用未见 schema 评测。</li><li>终态可验证时，RL 奖任务成功，不奖 JSON 合法本身。</li><li>出处：function calling 产品协议；Toolformer 为对照的另一条数据路。</li></ul>',13))])}const D=i(h,[["render",m]]);export{f as __pageData,D as default};
